static unsigned short read_le16(const unsigned char * p)
{
    return (unsigned short)p[0] | ((unsigned short)p[1] << 8);
}

static unsigned int read_le32(const unsigned char * p)
{
    return (unsigned int)p[0] |
           ((unsigned int)p[1] << 8) |
           ((unsigned int)p[2] << 16) |
           ((unsigned int)p[3] << 24);
}

static void write_le16(unsigned char * p, unsigned short v)
{
    p[0] = (unsigned char)(v & 0xff);
    p[1] = (unsigned char)((v >> 8) & 0xff);
}

static void write_le32(unsigned char * p, unsigned int v)
{
    p[0] = (unsigned char)(v & 0xff);
    p[1] = (unsigned char)((v >> 8) & 0xff);
    p[2] = (unsigned char)((v >> 16) & 0xff);
    p[3] = (unsigned char)((v >> 24) & 0xff);
}

static int convert_stereo_wav_to_mono(const char * stereo_path, const char * mono_path)
{
    FILE * in;
    FILE * out;
    unsigned char riff[12];
    unsigned char chunk_header[8];
    unsigned char fmt[64];
    unsigned char out_header[44];
    unsigned int data_size = 0;
    long data_offset = -1;
    unsigned short audio_format = 0;
    unsigned short channels = 0;
    unsigned short bits_per_sample = 0;
    unsigned short block_align = 0;
    unsigned int source_rate = 0;
    unsigned int mono_data_size;
    unsigned int sample_count;
    unsigned int mono_sample_count;
    unsigned int acc = 0;

    in = fopen(stereo_path, "rb");
    if(in == NULL) {
        return -1;
    }

    if(fread(riff, 1, sizeof(riff), in) != sizeof(riff)) {
        fclose(in);
        return -1;
    }

    if(memcmp(riff, "RIFF", 4) != 0 || memcmp(riff + 8, "WAVE", 4) != 0) {
        fclose(in);
        return -1;
    }

    while(fread(chunk_header, 1, sizeof(chunk_header), in) == sizeof(chunk_header)) {
        unsigned int chunk_size = read_le32(chunk_header + 4);
        long chunk_data_pos = ftell(in);

        if(memcmp(chunk_header, "fmt ", 4) == 0) {
            unsigned int read_size = chunk_size;
            if(read_size > sizeof(fmt)) {
                read_size = sizeof(fmt);
            }

            if(fread(fmt, 1, read_size, in) != read_size) {
                fclose(in);
                return -1;
            }

            if(chunk_size > read_size && fseek(in, chunk_size - read_size, SEEK_CUR) != 0) {
                fclose(in);
                return -1;
            }

            audio_format = read_le16(fmt);
            channels = read_le16(fmt + 2);
            source_rate = read_le32(fmt + 4);
            block_align = read_le16(fmt + 12);
            bits_per_sample = read_le16(fmt + 14);
        }
        else if(memcmp(chunk_header, "data", 4) == 0) {
            data_offset = chunk_data_pos;
            data_size = chunk_size;
            if(fseek(in, chunk_size, SEEK_CUR) != 0) {
                fclose(in);
                return -1;
            }
        }
        else {
            if(fseek(in, chunk_size, SEEK_CUR) != 0) {
                fclose(in);
                return -1;
            }
        }

        if(chunk_size & 1) {
            fseek(in, 1, SEEK_CUR);
        }
    }

    if(audio_format != 1 ||
       bits_per_sample != 16 ||
       channels == 0 ||
       channels > 2 ||
       block_align == 0 ||
       block_align > sizeof((unsigned char[4]){0}) ||
       source_rate < 16000 ||
       data_offset < 0) {
        fclose(in);
        return -1;
    }

    sample_count = data_size / block_align;
    mono_sample_count = (unsigned int)(((unsigned long long)sample_count * 16000) / source_rate);
    mono_data_size = mono_sample_count * 2;

    out = fopen(mono_path, "wb");
    if(out == NULL) {
        fclose(in);
        return -1;
    }

    memset(out_header, 0, sizeof(out_header));
    memcpy(out_header, "RIFF", 4);
    write_le32(out_header + 4, 36 + mono_data_size);
    memcpy(out_header + 8, "WAVEfmt ", 8);
    write_le32(out_header + 16, 16);
    write_le16(out_header + 20, 1);
    write_le16(out_header + 22, 1);
    write_le32(out_header + 24, 16000);
    write_le32(out_header + 28, 16000 * 2);
    write_le16(out_header + 32, 2);
    write_le16(out_header + 34, 16);
    memcpy(out_header + 36, "data", 4);
    write_le32(out_header + 40, mono_data_size);

    if(fwrite(out_header, 1, sizeof(out_header), out) != sizeof(out_header)) {
        fclose(in);
        fclose(out);
        return -1;
    }

    if(fseek(in, data_offset, SEEK_SET) != 0) {
        fclose(in);
        fclose(out);
        return -1;
    }

    for(unsigned int i = 0; i < sample_count; i++) {
        unsigned char frame[4] = {0};
        unsigned char mono[2];
        short left;
        short right;
        short mixed;

        if(fread(frame, 1, block_align, in) != block_align) {
            fclose(in);
            fclose(out);
            return -1;
        }

        left = (short)read_le16(frame);
        right = channels == 2 ? (short)read_le16(frame + 2) : left;
        mixed = (short)(((int)left + (int)right) / 2);

        acc += 16000;
        if(acc >= source_rate) {
            acc -= source_rate;
            write_le16(mono, (unsigned short)mixed);

            if(fwrite(mono, 1, sizeof(mono), out) != sizeof(mono)) {
                fclose(in);
                fclose(out);
                return -1;
            }
        }
    }

    fclose(in);
    fclose(out);
    return 0;
}

static int baidu_speech_recognition(const char * audio_file, char * text, size_t text_size)
{
    char cmd[2048];
    char response[8192];
    char err_msg[256];
    int err_no = -1;

    snprintf(cmd, sizeof(cmd),
             "curl -s --connect-timeout 8 -m 25 -X POST -H \"Content-Type: audio/wav;rate=16000\" "
             "\"%s?dev_pid=%s&cuid=%s&token=%s\" --data-binary \"@%s\"",
             BAIDU_ASR_URL, BAIDU_DEV_PID, BAIDU_CUID, BAIDU_TOKEN, audio_file);

    if(run_command_capture(cmd, response, sizeof(response)) != 0) {
        snprintf(text, text_size,
                 "语音识别失败：curl 无响应。请测试：ping -c 3 vop.baidu.com; curl -I http://vop.baidu.com");
        return -1;
    }

    write_text_file(BAIDU_RESPONSE_LOG, response);

    if(json_extract_asr_result(response, text, text_size) == 0 && !is_blank_text(text)) {
        return 0;
    }

    json_extract_int(response, "err_no", &err_no);
    if(json_extract_string(response, "err_msg", err_msg, sizeof(err_msg)) == 0) {
        snprintf(text, text_size,
                 "语音识别失败：err_no=%d, err_msg=%s\n原始返回：/tmp/baidu_asr_response.txt",
                 err_no, err_msg);
    }
    else {
        snprintf(text, text_size,
                 "语音识别失败：未解析到有效结果\n返回前 200 字：%.200s\n原始返回：/tmp/baidu_asr_response.txt",
                 response);
    }

    return -1;
}

static int write_coze_request(const char * question, char * path, size_t path_size)
{
    FILE * fp;
    char escaped_question[2048];

    snprintf(path, path_size, "/tmp/coze_request_%ld_%d.json", (long)time(NULL), (int)getpid());
    fp = fopen(path, "w");
    if(fp == NULL) {
        return -1;
    }

    json_escape(question, escaped_question, sizeof(escaped_question));

    fprintf(fp,
            "{\"bot_id\":\"%s\",\"user_id\":\"%s\",\"stream\":true,"
            "\"additional_messages\":[{\"content\":\"%s\",\"content_type\":\"text\","
            "\"role\":\"user\",\"type\":\"question\"}],\"parameters\":{}}",
            COZE_BOT_ID, COZE_USER_ID, escaped_question);

    fclose(fp);
    return 0;
}

static int get_agent_answer(const char * question, char * answer, size_t answer_size)
{
    char request_path[128];
    char cmd[1024];
    char raw_preview[4096] = {0};
    char log_cmd[1280];
    char fallback_answer[4096] = {0};
    FILE * response_fp;

    answer[0] = '\0';
    if(write_coze_request(question, request_path, sizeof(request_path)) != 0) {
        snprintf(answer, answer_size, "智能体请求失败：无法创建临时请求文件");
        return -1;
    }

    write_text_file(COZE_RESPONSE_LOG, "");
    snprintf(cmd, sizeof(cmd),
             "curl -k -sS -N --connect-timeout 8 -m 60 -X POST '%s' "
             "-H \"Authorization: Bearer %s\" "
             "-H \"Content-Type: application/json\" "
             "--data-binary '@%s'",
             COZE_API_URL, COZE_TOKEN, request_path);

    snprintf(log_cmd, sizeof(log_cmd), "%s > %s 2>&1", cmd, COZE_RESPONSE_LOG);
    system(log_cmd);
    remove(request_path);

    if(read_file_capture(COZE_RESPONSE_LOG, raw_preview, sizeof(raw_preview)) != 0) {
        snprintf(answer, answer_size,
                 "智能体请求失败：curl 没有返回内容。请测试：curl -k -I https://api.coze.cn");
        return -1;
    }

    response_fp = fopen(COZE_RESPONSE_LOG, "r");
    if(response_fp != NULL) {
        char line[2048];
        char current_event[96] = {0};
        while(fgets(line, sizeof(line), response_fp) != NULL) {
            char chunk[1024];
            const char * data = line;
            bool is_answer_type;
            bool is_delta;
            bool is_completed;

            line[strcspn(line, "\r\n")] = '\0';
            if(strncmp(line, "event:", 6) == 0) {
                snprintf(current_event, sizeof(current_event), "%s", line + 6);
                continue;
            }

            if(strncmp(line, "data:", 5) == 0) {
                data = line + 5;
            }

            is_answer_type = strstr(data, "\"type\":\"answer\"") != NULL;
            is_delta = strcmp(current_event, "conversation.message.delta") == 0;
            is_completed = strcmp(current_event, "conversation.message.completed") == 0;

            if(!is_answer_type ||
               json_extract_string(data, "content", chunk, sizeof(chunk)) != 0 ||
               is_blank_text(chunk)) {
                continue;
            }

            if(is_delta) {
                append_text(answer, answer_size, chunk);
            }
            else if(is_completed && is_blank_text(fallback_answer)) {
                snprintf(fallback_answer, sizeof(fallback_answer), "%s", chunk);
            }
        }
        fclose(response_fp);
    }

    if(is_blank_text(answer) && !is_blank_text(fallback_answer)) {
        snprintf(answer, answer_size, "%s", fallback_answer);
    }

    if(!is_blank_text(answer)) {
        return 0;
    }

    {
        char chunk[1024];
        if(json_extract_string(raw_preview, "content", chunk, sizeof(chunk)) == 0 &&
           !is_blank_text(chunk) &&
           strstr(raw_preview, "\"type\":\"answer\"") != NULL) {
            snprintf(answer, answer_size, "%s", chunk);
            return 0;
        }
    }

    if(json_extract_string(raw_preview, "msg", answer, answer_size) == 0 && !is_blank_text(answer)) {
        char tmp[4096];
        snprintf(tmp, sizeof(tmp), "智能体请求失败：%s", answer);
        snprintf(answer, answer_size, "%s", tmp);
    }
    else {
        snprintf(answer, answer_size,
                 "智能体请求失败：未获取到回答\n返回前 500 字：%.500s\n原始返回：/tmp/coze_response.txt",
                 raw_preview);
    }

    return -1;
}

