{
    char recognized[1024];
    char record_cmd[512];
    char record_error[768];
    int ret;
    bool conversion_failed = false;

    (void)arg;

    queue_status("正在录音，请说出需要提问的问题...");
    system("killall arecord 2>/dev/null");
    system("rm -f " RECORD_ERROR_LOG);
    system("rm -f " AUDIO_FILE " " STEREO_AUDIO_FILE);
    usleep(100000);

    snprintf(record_cmd, sizeof(record_cmd),
             "arecord -D plughw:0,0 -d %d -f S16_LE -r 16000 -c 1 %s >/dev/null 2>" RECORD_ERROR_LOG,
             RECORD_SECONDS, AUDIO_FILE);

    ret = system(record_cmd);
    if(ret != 0) {
        snprintf(record_cmd, sizeof(record_cmd),
                 "arecord -D plughw:0,0 -d %d -f S16_LE -r 48000 -c 2 %s >/dev/null 2>>" RECORD_ERROR_LOG,
                 RECORD_SECONDS, STEREO_AUDIO_FILE);
        conversion_failed = false;
        ret = system(record_cmd);
        if(ret == 0 && convert_stereo_wav_to_mono(STEREO_AUDIO_FILE, AUDIO_FILE) != 0) {
            ret = -1;
            conversion_failed = true;
        }
    }
    if(ret != 0) {
        snprintf(record_cmd, sizeof(record_cmd),
                 "arecord -D hw:0,0 -d %d -f S16_LE -r 48000 -c 2 %s >/dev/null 2>>" RECORD_ERROR_LOG,
                 RECORD_SECONDS, STEREO_AUDIO_FILE);
        conversion_failed = false;
        ret = system(record_cmd);
        if(ret == 0 && convert_stereo_wav_to_mono(STEREO_AUDIO_FILE, AUDIO_FILE) != 0) {
            ret = -1;
            conversion_failed = true;
        }
    }

    if(file_size(AUDIO_FILE) > 1024) {
        ret = 0;
        conversion_failed = false;
    }
    else if(file_size(STEREO_AUDIO_FILE) > 1024 &&
            convert_stereo_wav_to_mono(STEREO_AUDIO_FILE, AUDIO_FILE) == 0 &&
            file_size(AUDIO_FILE) > 1024) {
        ret = 0;
        conversion_failed = false;
    }

    if(ret != 0) {
        queue_status("录音失败：请检查麦克风和 arecord");
        if(conversion_failed) {
            queue_answer("录音成功，但 WAV 转换为 16000Hz 单声道失败。请在开发板执行：ls -l /tmp/assistant_question_stereo.wav");
        }
        else if(read_file_capture(RECORD_ERROR_LOG, record_error, sizeof(record_error)) == 0) {
            char msg[1024];
            snprintf(msg, sizeof(msg),
                     "录音失败，开发板返回：\n%s\n请测试：arecord -D plughw:0,0 -d 3 -f S16_LE -r 48000 -c 2 /tmp/test.wav",
                     record_error);
            queue_answer(msg);
        }
        else {
            queue_answer("录音失败：请检查麦克风是否可用，或确认 arecord 已安装。");
        }
        finish_job();
        return NULL;
    }

    queue_status("录音完成，正在调用百度语音识别...");
    if(baidu_speech_recognition(AUDIO_FILE, recognized, sizeof(recognized)) == 0) {
        char tip[1400];

        queue_question(recognized);
        snprintf(tip, sizeof(tip), "识别结果：%s\n\n请点击发送按钮提交给智能体。", recognized);
        queue_answer(tip);
        queue_status("识别完成，可点击发送按钮");
    }
    else {
        queue_answer(recognized);
        queue_status("语音识别失败");
    }

    finish_job();
    return NULL;
}

static void * send_worker(void * arg)
{
    char * question = (char *)arg;
    char answer[4096];

    queue_status("正在请求智能体，请稍候...");
    if(get_agent_answer(question, answer, sizeof(answer)) == 0) {
        queue_answer(answer);
        queue_status("回答完成");
    }
    else {
        queue_answer(answer);
        queue_status("智能体请求失败");
    }

    free(question);
    finish_job();
    return NULL;
}

void RecordAudio(lv_event_t * e)
{
    pthread_t tid;

    (void)e;
    printf("%s\n", assistant_build_mark);

    if(!try_begin_job()) {
        lv_label_set_text(ui_Label1, "当前任务正在执行，请稍候");
        return;
    }

    lv_textarea_set_text(ui_TextArea1, "");
    lv_textarea_set_text(ui_TextArea2, "正在录音，请说出需要提问的问题...");
    lv_label_set_text(ui_Label1, "正在录音...");

    if(pthread_create(&tid, NULL, record_worker, NULL) != 0) {
        lv_textarea_set_text(ui_TextArea2, "录音线程创建失败");
        lv_label_set_text(ui_Label1, "录音线程创建失败");
        finish_job();
        return;
    }

    pthread_detach(tid);
}

void StopRecording(lv_event_t * e)
{
    (void)e;
    system("killall arecord 2>/dev/null");
    lv_label_set_text(ui_Label1, "已停止录音");
}

void SendQuestion(lv_event_t * e)
{
    const char * question;
    char * question_copy;
    pthread_t tid;

    (void)e;

    if(!try_begin_job()) {
        lv_label_set_text(ui_Label1, "当前任务正在执行，请稍候");
        return;
    }

    question = lv_textarea_get_text(ui_TextArea1);
    if(is_blank_text(question)) {
        lv_textarea_set_text(ui_TextArea2, "请先通过语音输入问题，或在问题框中输入文字。");
        lv_label_set_text(ui_Label1, "问题为空");
        finish_job();
        return;
    }

    question_copy = duplicate_text(question);
    if(question_copy == NULL) {
        lv_textarea_set_text(ui_TextArea2, "内存不足，无法发送问题。");
        lv_label_set_text(ui_Label1, "发送失败");
        finish_job();
        return;
    }

    lv_textarea_set_text(ui_TextArea2, "问题已提交，正在等待智能体回答...");
    lv_label_set_text(ui_Label1, "正在请求智能体...");

    if(pthread_create(&tid, NULL, send_worker, question_copy) != 0) {
        free(question_copy);
        lv_textarea_set_text(ui_TextArea2, "智能体线程创建失败");
        lv_label_set_text(ui_Label1, "发送失败");
        finish_job();
        return;
    }

    pthread_detach(tid);
}

void assistant_ui_poll(void)
{
    bool update_status = false;
    bool update_question = false;
    bool update_answer = false;
    char status[sizeof(pending_status)];
    char question[sizeof(pending_question)];
    char answer[sizeof(pending_answer)];

    pthread_mutex_lock(&state_lock);

    if(dirty_status) {
        snprintf(status, sizeof(status), "%s", pending_status);
        dirty_status = false;
        update_status = true;
    }

    if(dirty_question) {
        snprintf(question, sizeof(question), "%s", pending_question);
        dirty_question = false;
        update_question = true;
    }

    if(dirty_answer) {
        snprintf(answer, sizeof(answer), "%s", pending_answer);
        dirty_answer = false;
        update_answer = true;
    }

    pthread_mutex_unlock(&state_lock);

    if(update_question && ui_TextArea1 != NULL) {
        lv_textarea_set_text(ui_TextArea1, question);
        lv_textarea_set_cursor_pos(ui_TextArea1, 0);
        lv_obj_scroll_to_y(ui_TextArea1, 0, LV_ANIM_OFF);
        lv_obj_invalidate(ui_TextArea1);
    }

    if(update_answer && ui_TextArea2 != NULL) {
        lv_textarea_set_text(ui_TextArea2, answer);
    }

    if(update_status && ui_Label1 != NULL) {
        lv_label_set_text(ui_Label1, status);
    }
}
